'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var format = require( '@stdlib/string/format' );
var get = require( '@stdlib/utils/json-pointer/get' );
var remove = require( '@stdlib/utils/json-patch/ops/remove' );
var add = require( '@stdlib/utils/json-patch/ops/add' );


// MAIN //

/**
* Applies a JSON Patch `move` operation to a document immutably.
*
* ## Notes
*
* -   Implements the `move` operation per RFC 6902 §4.4.
* -   Functionally equivalent to a `remove` at `from` followed by an `add` at `path`.
* -   The `from` location must exist.
* -   The `path` must not be a child of `from` (cannot move into own descendant).
* -   Returns a new document; the original is not modified (structural sharing).
*
* @param {(Object|Array)} document - source JSON document
* @param {string} from - JSON Pointer to move from
* @param {string} path - JSON Pointer to move to
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a string
* @throws {TypeError} third argument must be a string
* @throws {Error} cannot move a value into its own descendant
* @throws {Error} `from` must reference an existing location
* @returns {(Object|Array)} new document with the value moved
*
* @example
* var doc = { 'foo': 1, 'bar': {} };
* var out = move( doc, '/foo', '/bar/baz' );
* // returns { 'bar': { 'baz': 1 } }
*
* @example
* var doc = { 'a': { 'b': 1 }, 'c': 2 };
* var out = move( doc, '/c', '/a/c' );
* // returns { 'a': { 'b': 1, 'c': 2 } }
*/
function move( document, from, path ) {
	var result;
	var val;

	if ( !isPlainObject( document ) && !isArray( document ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an object or an array. Value: `%s`.', document ) );
	}
	if ( !isString( from ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a string. Value: `%s`.', from ) );
	}
	if ( !isString( path ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a string. Value: `%s`.', path ) );
	}

	// Ancestor check: path must not be a child of from (e.g., moving /a to /a/b/c is invalid):
	if ( from !== '' && path.indexOf( from + '/' ) === 0 ) {
		throw new Error( format( 'invalid operation. Cannot move a value into its own descendant. From: `%s`. Path: `%s`.', from, path ) );
	}

	// If from and path are the same, this is a no-op:
	if ( from === path ) {
		return document;
	}

	val = get( document, from );

	// Remove from source:
	result = remove( document, from );

	// Add to destination:
	result = add( result, path, val );

	return result;
}


// EXPORTS //

module.exports = move;
